// Brand colors are evidence, never sampled from the food, skin or scenery.
function brandPalette(plan    ,l    ){
 const hex=(v    )=>/^#[0-9a-f]{6}$/i.test(String(v||''))?String(v).toLowerCase():'';
 const lum=(v       )=>{const c=v.slice(1).match(/../g) .map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]};
 const contrast=(a       ,b       )=>(Math.max(lum(a),lum(b))+.05)/(Math.min(lum(a),lum(b))+.05);
 const readable=(bg       )=>contrast(bg,'#ffffff')>=contrast(bg,'#151515')?'#ffffff':'#151515';
 const owner=l.data.brandPalette;const locked=owner?.locked===true;const legacy=hex(l.data.color);
 const evidence=plan.brandReferenceEvidence===true||Array.isArray(l.data.brandReferences)&&l.data.brandReferences.some((r    )=>/^data:image\/(jpeg|png|webp);base64,/.test(r.data||''));
 const source=locked?'owner':legacy?'owner-accent':evidence?'brand-reference':'unconfirmed';
 const background=locked?hex(owner.background)||'#151515':evidence?hex(plan.background)||'#151515':'#151515';
 const text=locked?hex(owner.text)||readable(background):evidence?hex(plan.text)||readable(background):'#ffffff';
 const accent=(locked?hex(owner.accent):legacy|| (evidence?hex(plan.accent):''))||'#ffffff';
 const safeText=contrast(background,text)>=4.5?text:readable(background);
 return {background,text:safeText,accent,actionText:readable(accent),accentText:contrast(background,accent)>=3?accent:safeText,source,contrast:Number(contrast(background,safeText).toFixed(2))};
}
