function segmentDirection(value       ){
 if(/lanch|burger|hamb|restaur|pizza|caf[eé]|padar|sorvet/i.test(value))return "Gastronomia cinematográfica: comida real dominante; nome monumental; acento da foto; seção editorial; CTA consultar/pedir via WhatsApp; não inventar cardápio.";
 if(/barbear|barber/i.test(value))return "Barbearia editorial: contraste escuro, grelha de revista assimétrica, tipografia condensada, retratos/ambiente reais, CTA agendar pelo WhatsApp.";
 if(/clin|clín|dent|saúde|saude|beleza|est[eé]tica/i.test(value))return "Saúde e beleza: editorial arejado, fundo claro, contraste acessível, retratos reais, títulos sóbrios; contato para informações, sem prometer resultado.";
 if(/academ|fitness|oficina|auto|lava/i.test(value))return "Esportivo e técnico: tipografia robusta, cor da identidade real, foto em grande escala, composição dinâmica; CTA solicitar atendimento.";
 if(/roup|moda|hotel|pousada|m[oó]ve|arquit/i.test(value))return "Editorial de coleção: fotografia real em grande escala, composição assimétrica, títulos elegantes e galeria sem duplicar imagens; CTA consultar disponibilidade.";
 return "Serviço local: editorial comercial claro, foto real do negócio, hierarquia tipográfica forte, seções de apresentação e localização, CTA conversar; não inventar serviços ou provas sociais.";
}
