  if(!hit||Date.now()-hit.at>21600000){try{const result=await request("https://api.groq.com/openai/v1/chat/completions",{method:"POST",timeout:45000,headers:{Authorization:"Bearer "+required(env.LLM_PROVIDER_API_KEY,"Pesquisa de publicações"),"Content-Type":"application/json"},body:JSON.stringify({model:"openai/gpt-oss-20b",tools:[{type:"browser_search"}],reasoning_effort:"low",max_tokens:1200,messages:[{role:"system",content:'Pesquise publicações públicas de um perfil de Instagram já confirmado. Não redescubra o perfil e não misture contas parecidas. Use browser_search. Busque fotos de produtos do perfil e retorne só JSON {"urls":[até 3 URLs https://www.instagram.com/p/.../ ou /reel/.../ encontrados]}. Se não houver resultado confirmado, retorne urls vazio. Não invente URLs.'},{role:"user",content:JSON.stringify({profile:hint,handle,name,city,query:'site:instagram.com "'+handle+'" ("Photo" OR "foto" OR "burger")'})}]})});const raw=result.choices?.[0]?.message?.content||"";const parsed=JSON.parse(raw.slice(raw.indexOf("{"),raw.lastIndexOf("}")+1));posts=(parsed.urls||[]).map(instagramURL).filter((u    )=>/\/(p|reel)\//.test(u)).slice(0,3);instagramPostCache.set(hint,{at:Date.now(),urls:posts});if(instagramPostCache.size>200)instagramPostCache.delete(instagramPostCache.keys().next().value )}catch(e    ){console.warn("instagram.posts",e.message)}}
  const ownership=new RegExp('(^|[^a-zA-Z0-9_.])'+handle.replaceAll('.', '\\.')+'(?=$|[^a-zA-Z0-9_.])','i');
